import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int t = fs.nextInt();
        int n = fs.nextInt();

        int[] x = new int[n];
        for (int i = 0; i < n; i++) {
            x[i] = fs.nextInt();
        }

        Arrays.sort(x);

        double min = Math.min((x[0] + x[1]) / 2.0,
                              t - (x[n - 2] + x[n - 1]) / 2.0);

        for (int i = 1; i < n - 1; i++) {
            min = Math.min(min, (x[i + 1] - x[i - 1]) / 2.0);
        }

        System.out.printf(Locale.US, "%.2f%n", min);
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }
    }
}
